// (1,2,3,4 -> AND -> out_and)
// (1,2,3,4 -> OR  -> out_or)
// (1,2,3,4 -> XOR -> out_xor) forms the same critical path as the
// combinational circuit, so the registerless version is faster.
module TopModule(
    input  [3:0] in,
    output        out_and,
    output        out_or,
    output        out_xor
);
    wire and0 = in[0] & in[1];
    wire and1 = in[2] & in[3];
    wire and2 = and0 & and1;
    wire or0  = in[0] | in[1];
    wire or1  = in[2] | in[3];
    wire or2  = or0 | or1;
    wire xor0 = in[0] ^ in[1];
    wire xor1 = in[2] ^ in[3];
    wire xor2 = xor0 ^ xor1;
    assign out_and = and2;
    assign out_or  = or2;
    assign out_xor = xor2;
endmodule

